-- 仅回滚本 migration 新增的推荐词条。任务和 Agent 的 tag_names 是历史快照，不使用
-- 外键引用 tags 表，因此删除推荐项不会破坏既有业务记录或自定义标签。
BEGIN;

DELETE FROM tags
 WHERE id = ANY(ARRAY[
  '50000000-0000-4000-9000-000000000001','50000000-0000-4000-9000-000000000002',
  '50000000-0000-4000-9000-000000000003','50000000-0000-4000-9000-000000000004',
  '50000000-0000-4000-9000-000000000005','50000000-0000-4000-9000-000000000006',
  '50000000-0000-4000-9000-000000000007','50000000-0000-4000-9000-000000000008',
  '50000000-0000-4000-9000-000000000009','50000000-0000-4000-9000-000000000010',
  '50000000-0000-4000-9000-000000000011','50000000-0000-4000-9000-000000000012',
  '50000000-0000-4000-9000-000000000013','50000000-0000-4000-9000-000000000014',
  '50000000-0000-4000-9000-000000000015','50000000-0000-4000-9000-000000000016',
  '50000000-0000-4000-9000-000000000017','50000000-0000-4000-9000-000000000018',
  '50000000-0000-4000-9000-000000000019','50000000-0000-4000-9000-000000000020',
  '50000000-0000-4000-9000-000000000021','50000000-0000-4000-9000-000000000022',
  '50000000-0000-4000-9000-000000000023','50000000-0000-4000-9000-000000000024',
  '50000000-0000-4000-9000-000000000025','50000000-0000-4000-9000-000000000026',
  '50000000-0000-4000-9000-000000000027','50000000-0000-4000-9000-000000000028',
  '50000000-0000-4000-9000-000000000029','50000000-0000-4000-9000-000000000030'
 ]::UUID[]);

COMMIT;
